package at.andrew.squashtap;

import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
import org.junit.Test;import static org.junit.Assert.*;

public class MatchRetirementTest {
    public static void main(String[] args)throws Exception{
        if(args.length==0){MatchResult r=new MatchResult("browser-retired","2026-11-07",1,3,new int[][]{{11,4},{6,8}},0,0,"",0),n=new MatchResult("browser-normal","2026-11-07",2,3,new int[][]{{11,3},{11,5}});System.out.print(MatchCsv.export(Arrays.asList(r,n),new OpponentDirectory()));}
        else{java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=System.in.read(buffer))!=-1){if(bytes.size()+n>MatchCsv.MAX_CHARS)throw new IllegalArgumentException("Too large");bytes.write(buffer,0,n);}java.util.List<MatchCsv.Row> rows=MatchCsv.parse(new String(bytes.toByteArray(),StandardCharsets.UTF_8));java.util.List<MatchResult> results=new java.util.ArrayList<>();for(MatchCsv.Row row:rows)results.add(row.result);MatchStatistics s=MatchStatistics.from(results);System.out.print(rows.size()+":"+s.matchesWon+":"+s.matchesLost+":"+s.setsWon+":"+s.setsLost+":"+s.pointsFor+":"+s.pointsAgainst);}
    }
    static class TestClock extends Clock{Instant now=Instant.parse("2026-11-07T09:00:00Z");public ZoneId getZone(){return ZoneId.of("Europe/Vienna");}public Clock withZone(ZoneId z){return Clock.fixed(now,z);}public Instant instant(){return now;}void advance(long seconds){now=now.plusSeconds(seconds);}}
    private MatchBook book(TestClock clock){return new MatchBook(new MatchState("retirement",3),clock);}
    private void winSet(MatchBook b,int player){for(int i=0;i<11;i++)assertTrue(b.add(player));}
    private MatchBook fixture(String kind)throws Exception{return MatchBook.decode(new String(Files.readAllBytes(Paths.get("android/test-fixtures/book-v2-"+kind+".txt")),StandardCharsets.UTF_8).trim(),new TestClock());}
    private MatchResult retired(String id,int player){return new MatchResult(id,"2026-11-07",1,3,new int[][]{{11,4},{6,8}},0,0,"",player);}
    @Test public void eitherPlayerCanQuitWithoutAwardingPointsOrSets(){for(int player=0;player<2;player++){MatchState m=new MatchState("quit",5);m.add(0);m.add(1);m.add(1);assertTrue(m.retire(player));assertTrue(m.complete());assertEquals(1-player,m.winner());assertEquals(1,m.game().blue());assertEquals(2,m.game().red());assertEquals(0,m.gamesWon(0));assertEquals(0,m.gamesWon(1));}}
    @Test public void retirementBetweenSetsKeepsOnlyTheSetActuallyWon(){MatchBook b=book(new TestClock());winSet(b,0);assertTrue(b.retire(0));MatchResult r=b.result("retirement");assertEquals(1,r.winner());assertEquals(1,r.gamesWon(0));assertEquals(0,r.gamesWon(1));assertEquals(1,r.gameCount());}
    @Test public void retiredMatchesRejectPointsNextFormatAndRepeatedRetirement(){MatchState m=new MatchState("quit",5);m.add(1);m.retire(1);assertFalse(m.add(0));assertFalse(m.nextGame());assertFalse(m.changeBestOf(3));assertFalse(m.retire(0));assertEquals(0,m.winner());}
    @Test public void naturallyCompletedMatchCannotBeRetired(){MatchBook b=book(new TestClock());winSet(b,0);b.nextGame();winSet(b,0);String before=b.encode();assertFalse(b.retire(0));assertEquals(before,b.encode());}
    @Test public void undoRetirementPreservesEveryRallyThenAllowsNormalUndo(){MatchState m=new MatchState("quit",3);m.add(0);m.add(1);m.retire(1);m=MatchState.decode(m.encode());assertTrue(m.undo());assertFalse(m.complete());assertEquals(1,m.game().red());assertEquals(1,m.game().blue());assertTrue(m.undo());assertEquals(0,m.game().red());}
    @Test public void zeroPointRetirementRecordsFinishWithoutInventingStartOrDuration(){TestClock c=new TestClock();MatchBook b=book(c);b.retire(0);MatchResult r=b.result("retirement");assertEquals(0,r.startedAt);assertEquals(c.now.toEpochMilli(),r.finishedAt);assertEquals("Not recorded",r.durationText());assertEquals(0,r.gamesWon(1));assertEquals(0,r.points(0,0));assertTrue(b.undo());assertFalse(b.current().retired());}
    @Test public void retirementTimingAndB3RoundtripKeepTheOriginalStart(){TestClock c=new TestClock();MatchBook b=book(c);b.add(0);c.advance(600);b.add(1);b.retire(1);String encoded=b.encode();assertTrue(encoded.startsWith("B4:"));b=MatchBook.decode(encoded,c);assertEquals(encoded,b.encode());assertEquals(600000,b.result("retirement").durationMillis());assertEquals(1,b.result("retirement").retiredPlayer);assertEquals("Opponent retired · You won",b.result("retirement").outcomeText());}
    @Test public void undoAndReRetirementReuseTheDailyReferenceAndDoNotDoubleCount(){TestClock c=new TestClock();MatchBook b=book(c);b.add(0);b.retire(1);int number=b.result("retirement").number;b.undo();assertEquals(0,b.count());c.advance(20);b.retire(0);assertEquals(number,b.result("retirement").number);assertEquals(1,b.count());assertEquals(1,MatchStatistics.from(b.newestFirst()).matchesLost);}
    @Test public void deletingThenUndoingRetirementDoesNotResurrectAResult(){MatchBook b=book(new TestClock());b.add(0);b.retire(1);b.delete("retirement");b=MatchBook.decode(b.encode());b.undo();b.retire(0);assertTrue(b.currentDeleted());assertEquals(0,b.count());}
    @Test public void statisticsUseTheRetirementWinnerButOnlyPlayedSetsAndPoints(){MatchStatistics s=MatchStatistics.from(Collections.singletonList(retired("quit",0)));assertEquals(0,s.matchesWon);assertEquals(1,s.matchesLost);assertEquals(1,s.setsWon);assertEquals(0,s.setsLost);assertEquals(1,s.setsPlayed());assertEquals(17,s.pointsFor);assertEquals(12,s.pointsAgainst);}
    @Test public void retirementCsvRoundtripsMixedHistoryAndLegacyExportsStaySchemaOne(){OpponentDirectory d=new OpponentDirectory();MatchResult r=retired("quit",1),normal=new MatchResult("normal","2026-11-07",2,3,new int[][]{{11,3},{11,5}});String csv=MatchCsv.export(Arrays.asList(normal,r),d);assertTrue(csv.startsWith("\ufeff"+MatchCsv.RETIREMENT_HEADER));List<MatchCsv.Row> rows=MatchCsv.parse(csv);assertEquals(-1,rows.get(0).result.retiredPlayer);assertEquals(1,rows.get(1).result.retiredPlayer);assertEquals(6,rows.get(1).result.points(1,0));assertTrue(MatchCsv.export(Collections.singletonList(normal),d).startsWith("\ufeff"+MatchCsv.HEADER+"\r\n\"1\""));}
    @Test public void retiredImportsDeduplicateAndDistinguishTheOtherRetirementWinner(){MatchBook b=book(new TestClock());OpponentDirectory d=new OpponentDirectory();String csv=MatchCsv.export(Collections.singletonList(retired("foreign",0)),d);MatchCsv.Plan first=MatchCsv.plan(b,d,MatchCsv.parse(csv));assertEquals(1,first.added);assertEquals(0,first.book.result("foreign").retiredPlayer);assertEquals(1,MatchCsv.plan(first.book,first.directory,MatchCsv.parse(csv)).duplicates);String other=MatchCsv.export(Collections.singletonList(retired("foreign",1)),d);assertEquals(1,MatchCsv.plan(first.book,first.directory,MatchCsv.parse(other)).conflicts);}
    @Test public void partialSetBeforeAnotherSetAndImpossibleFinalScoresAreRejected(){assertThrows(IllegalArgumentException.class,()->new MatchResult("bad","2026-11-07",1,3,new int[][]{{5,4},{11,3}},0,0,"",1));assertThrows(IllegalArgumentException.class,()->new MatchResult("bad","2026-11-07",1,3,new int[][]{{12,3}},0,0,"",1));assertThrows(IllegalArgumentException.class,()->new MatchResult("bad","2026-11-07",1,3,new int[][]{{11,3},{11,4}},0,0,"",0));}
    @Test public void malformedRetirementStateAndOutcomeMismatchAreRejected(){assertThrows(IllegalArgumentException.class,()->new MatchState("bad",3).retire(2));MatchBook b=book(new TestClock());b.add(0);b.retire(1);byte[] raw=Base64.getDecoder().decode(b.encode().substring(3));java.nio.ByteBuffer.wrap(raw).putInt(raw.length-4,0);assertThrows(IllegalArgumentException.class,()->MatchBook.decode("B4:"+Base64.getEncoder().encodeToString(raw)));}
    @Test public void b2ActiveMigrationKeepsRalliesHistoryCountersAndUndo()throws Exception{MatchBook b=fixture("active");assertTrue(b.encode().startsWith("B4:"));assertEquals(1,b.count());assertEquals(1,b.current().gamesWon(0));assertEquals(1,b.current().game().red());assertTrue(b.undo());assertEquals(1,b.current().game().red());assertEquals(0,b.current().game().blue());b.retire(1);assertEquals(3,b.result("v2-current").number);assertEquals(2,b.count());}
    @Test public void b2CompletedMigrationKeepsNormalOutcomeAndReferences()throws Exception{MatchBook b=fixture("completed");assertFalse(b.current().retired());assertEquals(-1,b.result("v2-current").retiredPlayer);assertEquals(3,b.result("v2-current").number);assertEquals(2,b.count());b.undo();b.retire(1);assertEquals(3,b.result("v2-current").number);}
    @Test public void b2DeletedCurrentStaysDeletedAfterMigrationAndRetirement()throws Exception{MatchBook b=fixture("deleted");assertTrue(b.currentDeleted());b.undo();b.retire(1);assertEquals(1,b.count());assertNull(b.result("v2-current"));}
}
